package com.giftmarket.admin.controller;import com.giftmarket.admin.dto.response.*;import com.giftmarket.admin.service.AdminReturnService;import com.giftmarket.global.response.ApiResponse;import com.giftmarket.order.entity.*;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/admin/returns") @RequiredArgsConstructor public class AdminReturnController{private final AdminReturnService service;@GetMapping public ApiResponse<AdminReturnPageResponse> all(@AuthenticationPrincipal Long adminId,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)ReturnRequestStatus status,@RequestParam(required=false)ReturnResponsibility responsibility){return ApiResponse.success(service.getReturns(adminId,page,size,keyword,status,responsibility));}@GetMapping("/{id}")public ApiResponse<AdminReturnDetailResponse> one(@AuthenticationPrincipal Long adminId,@PathVariable Long id){return ApiResponse.success(service.getReturn(adminId,id));}}
